## Why This Question Is Asked
This question tests understanding of stack augmentation, a practical pattern for maintaining auxiliary state. It demonstrates the ability to design data structures that support efficient queries while handling edge cases like duplicates and empty states.

## Key Concepts
- Two auxiliary stacks (minStack and maxStack) track running minima and maxima in sync with the main stack
- Each push/pop operation updates all three stacks atomically, preserving O(1) time complexity
- Duplicates are handled naturally since the min/max is recalculated at each step
- Empty stack edge cases must be handled (typically by checking stack length before accessing top)

## Code Example
```javascript
class MinMaxStack {
  constructor() {
    this.stack = [];
    this.minStack = [];
    this.maxStack = [];
  }

  push(x) {
    this.stack.push(x);
    this.minStack.push(
      this.minStack.length ? Math.min(x, this.minStack[this.minStack.length - 1]) : x
    );
    this.maxStack.push(
      this.maxStack.length ? Math.max(x, this.maxStack[this.maxStack.length - 1]) : x
    );
  }

  pop() {
    if (this.stack.length === 0) return undefined;
    this.minStack.pop();
    this.maxStack.pop();
    return this.stack.pop();
  }

  top() {
    return this.stack[this.stack.length - 1];
  }

  getMin() {
    return this.minStack[this.minStack.length - 1];
  }

  getMax() {
    return this.maxStack[this.maxStack.length - 1];
  }
}
```

## Why This Is Asked

This question tests mastery of rope-like data structures for dynamic sequences with cut-paste operations while maintaining fast range queries.

## Key Concepts

- **Implicit treap / rope**: Uses position as the key rather than explicit values
- **Split and merge operations**: Fundamental primitives for manipulating segments
- **Augmented data**: size and range sum maintained at each node
- **Edge cases**: Properly handling when dest overlaps with [l, r]

## Code Example

```javascript
class Node {
  constructor(v) {
    this.v = v;
    this.pr = Math.random();
    this.l = this.r = null;
    this.sz = 1;
    this.sum = v;
  }
}

function upd(t) {
  if (!t) return;
  t.sz = 1 + sz(t.l) + sz(t.r);
  t.sum = t.v + sum(t.l) + sum(t.r);
}

function split(t, k, l, r) {
  if (!t) return [null, null];
  if (sz(t.l) >= k) {
    let [a, b] = split(t.l, k, l, r);
    t.l = b; upd(t);
    return [a, t];
  } else {
    let [a, b] = split(t.r, k - sz(t.l) - 1, l, r);
    t.r = a; upd(t);
    return [t, b];
  }
}

function merge(a, b) {
  if (!a || !b) return a || b;
  if (a.pr < b.pr) {
    a.r = merge(a.r, b); upd(a); return a;
  } else {
    b.l = merge(a, b.l); upd(b); return b;
  }
}

function rangeSum(t, l, r) {
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, r - l + 1);
  let res = sum(b);
  t = merge(a, merge(b, c));
  return res;
}

function moveSegment(t, l, r, dest) {
  let len = r - l + 1;
  let [a, bc] = split(t, l);
  let [b, c] = split(bc, len);
  t = merge(a, c);

  let pos = dest <= l ? dest : dest - len;
  let [x, y] = split(t, pos);\n  return merge(merge(x, b), y);
}
```

## Why This Is Asked
Tests structuring a dynamic, duplicate-friendly grouping based on a stable signature.

## Key Concepts
- Canonical form via sorted letters for anagram grouping
- Nested maps to track per-word counts within a signature bucket
- Amortized update and linear-time retrieval relative to output size

## Code Example
```javascript
class AnagramMultiset {
  constructor(){ this.sigMap = new Map(); }
  _sig(w){ return w.split('').sort().join(''); }
  insert(word){ const s = this._sig(word); const bucket = this.sigMap.get(s) || new Map(); bucket.set(word, (bucket.get(word) || 0) + 1); this.sigMap.set(s, bucket); }
  erase(word){ const s = this._sig(word); const bucket = this.sigMap.get(s); if(!bucket) return; const c = (bucket.get(word) || 0) - 1; if(c<=0){ bucket.delete(word); if(bucket.size===0) this.sigMap.delete(s);} else { bucket.set(word, c); } }
  getAnagrams(word){ const s = this._sig(word); const bucket = this.sigMap.get(s); if(!bucket) return []; const res = []; for(const [w,c] of bucket) for(let i=0;i<c;i++) res.push(w); return res; }
}
```

